package com.receiptledger.v1;

import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.view.*;import android.widget.*;import com.receiptledger.v1.archive.ReceiptRepository;import com.receiptledger.v1.persistence.ReceiptRecord;import com.receiptledger.v1.ui.ReceiptDisplayFormatter;import java.util.*;import java.util.concurrent.*;

public final class LibraryActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private ReceiptRepository repository;private LinearLayout list;private TextView status;private long generation;
 @Override protected void onCreate(Bundle b){super.onCreate(b);repository=new ReceiptRepository(getApplicationContext());int p=dp(12);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(p,p,p,p);TextView title=new TextView(this);title.setText(R.string.library_title);title.setTextSize(23);LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);Button prices=new Button(this);prices.setText(R.string.open_price_history);prices.setOnClickListener(v->startActivity(new Intent(this,PriceHistoryActivity.class)));Button close=new Button(this);close.setText(R.string.close_library);close.setOnClickListener(v->finish());actions.addView(prices);actions.addView(close);status=new TextView(this);ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);scroll.addView(list,new ScrollView.LayoutParams(-1,-2));root.addView(title);root.addView(actions);root.addView(status);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1f));setContentView(root);}
 @Override protected void onResume(){super.onResume();reload();}
 private void reload(){long ticket=++generation;status.setText(R.string.library_loading);worker.execute(()->{List<ReceiptRecord> records=repository.listNewestFirst(200);runOnUiThread(()->{if(ticket!=generation)return;list.removeAllViews();status.setText(getString(R.string.library_count,records.size()));if(records.isEmpty()){TextView empty=new TextView(this);empty.setText(R.string.library_empty);list.addView(empty);return;}for(ReceiptRecord r:records){Button row=new Button(this);row.setAllCaps(false);row.setGravity(Gravity.START|Gravity.CENTER_VERTICAL);row.setText(ReceiptDisplayFormatter.summary(r));row.setOnClickListener(v->{Intent i=new Intent(this,ReceiptDetailActivity.class);i.putExtra(ReceiptDetailActivity.EXTRA_ID,r.id);startActivity(i);});list.addView(row,new LinearLayout.LayoutParams(-1,-2));}});});}
 @Override protected void onDestroy(){generation++;worker.shutdownNow();repository.close();super.onDestroy();}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
}
